458	func TestConcurrentDuplicateSubmissions(t *testing.T) {
459		now, _ := fixedClock(at(5))
460		b := NewBook(WithClock(now))
461		if err := b.RegisterVersion(RegisterRequest{ItemID: "seat", VersionID: "v1", UnitPrice: 7, Start: at(0)}); err != nil {
462			t.Fatal(err)
463		}
464		req := QuoteRequest{RequestID: "dup", ItemID: "seat", VersionID: "v1", Quantity: 3}
465	
466		const n = 32
467		outs := make([]Outcome, n)
468		errs := make([]error, n)
469		var wg sync.WaitGroup
470		for i := 0; i < n; i++ {
471			wg.Add(1)
472			go func(i int) {
473				defer wg.Done()
474				outs[i], errs[i] = b.Quote(req)
475			}(i)
476		}
477		wg.Wait()
478		for i := range outs {
479			if errs[i] != nil {
480				t.Fatalf("concurrent quote %d: %v", i, errs[i])
481			}
482			if outs[i] != outs[0] {
483				t.Fatalf("divergent first result: %+v vs %+v", outs[0], outs[i])
484			}
485		}
486		if !outs[0].Confirmed || outs[0].Total != 21 {
487			t.Fatalf("unexpected outcome: %+v", outs[0])
488		}
489		got, err := b.Lookup("dup")
490		if err != nil || got != outs[0] {
491			t.Fatalf("stored record: %+v (%v)", got, err)
492		}
493	}
