540		out, _ = b.Quote(QuoteRequest{RequestID: "q-new", ItemID: "seat", VersionID: "new", Quantity: 1})
541		if !out.Confirmed {
542			t.Fatalf("new version should be quotable at 11: %+v", out)
543		}
