96	// 即使交接点合法，替代版本也不能占用同项另一个已登记版本的有效时间：
97	// 不填结束时间会延伸进持续有效的 v3；结束时间只要晚于 4 月 1 日零点，
98	// 哪怕只超出一纳秒，或已经通过 Replaces 指定了被替代版本，仍必须返回 ErrOverlap。
99	func TestReplacementOverlapsFollowUpVersion(t *testing.T) {
100		cases := []struct {
101			name string
102			end  *time.Time
103		}{
104			{"不填结束时间-持续有效", nil},
105			{"结束晚于后续版本开始一纳秒", timePtr(rrFollowStart.Add(time.Nanosecond))},
106			{"结束晚于后续版本开始一分钟", timePtr(rrFollowStart.Add(time.Minute))},
107			{"结束晚于后续版本开始一整天", timePtr(rrFollowStart.Add(24 * time.Hour))},
108		}
109		for _, c := range cases {
110			t.Run(c.name, func(t *testing.T) {
111				b := newReplacementBaseBook(t)
112	
113				err := b.RegisterVersion(RegisterRequest{
114					ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180,
115					Start: rrHandoff, End: c.end, Replaces: "seat-v1",
116				})
117				if !errors.Is(err, ErrOverlap) {
118					t.Fatalf("替代版本占用后续版本有效时间应返回 ErrOverlap, got %v", err)
119				}
120	
121				// 失败不留痕迹：原两版不变，失败版本及其标识都不在查询结果中。
