194						round+1, old.VersionID, nv.VersionID, follow.VersionID)
195				}
196	
197				// 旧版本：登记结束仍是 3 月 31 日（永不因后续登记改变），
198				// 实际有效结束被截断到 3 月 10 日，并显示由 v2 替代。
199				if old.UnitPrice != 150 || !old.Start.Equal(rrOldStart) {
