237						round+1, follow.End, follow.EffectiveEnd)
238				}
239				if follow.Replaces != "" || follow.SupersededBy != "" {
240					t.Fatalf("第%d轮: 后续版本不应出现替代关系: Replaces=%q SupersededBy=%q",
241						round+1, follow.Replaces, follow.SupersededBy)
242				}
243			})
244		}
245	}
